82	            : OwnerDto.ContactPreferenceEnum.PHONE;
83	    }
84	
85	    Owner toOwner(OwnerDto ownerDto);
86	
87	    @Mapping(target = "id", ignore = true)
88	    @Mapping(target = "pets", ignore = true)
89	    Owner toOwner(OwnerFieldsDto ownerDto);
90	
91	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
92	
93	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
94	
95	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
96	        OwnerPageDto ownerPageDto = new OwnerPageDto();
97	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
98	        ownerPageDto.setPage(ownerPage.getNumber());
99	        ownerPageDto.setSize(ownerPage.getSize());
100	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
101	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
102	        return ownerPageDto;
