10	 * Single source of truth for an owner's derived {@code ageBand} — the band the owner falls into
11	 * based on their {@code birthDate} measured against their {@code registrationDate}:
12	 * {@code MINOR} when under 18, {@code ADULT} from 18 to 64 inclusive, and {@code SENIOR} at 65 or
13	 * over.
14	 *
15	 * <p>Derived at read time by the owner mapper from the already-stored {@code birthDate} and
16	 * {@code registrationDate}, so it needs no column of its own and can never drift. Absent
17	 * ({@code null}) when no birth date was supplied.
18	 */
19	public final class OwnerAgeBand {
20	
21	    private OwnerAgeBand() {
22	    }
23	
24	    /** The age band of an already-stored owner, or {@code null} when no birth date is recorded. */
25	    public static OwnerDto.AgeBandEnum ageBand(Owner owner) {
26	        return ageBand(owner.getBirthDate(), owner.getRegistrationDate());
27	    }
28	
29	    /**
30	     * The age band for a {@code birthDate} as measured against {@code asOf} (the registration
31	     * date); {@code null} when either date is absent.
32	     */
33	    public static OwnerDto.AgeBandEnum ageBand(LocalDate birthDate, LocalDate asOf) {
34	        if (birthDate == null || asOf == null) {
35	            return null;
36	        }
37	        int years = Period.between(birthDate, asOf).getYears();
38	        if (years < 18) {
39	            return OwnerDto.AgeBandEnum.MINOR;
40	        }
41	        if (years < 65) {
42	            return OwnerDto.AgeBandEnum.ADULT;
43	        }
44	        return OwnerDto.AgeBandEnum.SENIOR;
45	    }
46	}
